from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(
        encoding="utf-8"
    )
)

for role in ["validation", "audit"]:
    for name in ["popularity", "user_cf", lab["policy"]["selected"]]:
        card = lab["scorecards"][role][name]["warm"]
        print(role, name, card["recall"], card["ndcg"])
assert (
    lab["scorecards"]["audit"]["user_cf"]["warm"]["ndcg"]
    > lab["scorecards"]["audit"]["rrf_cf"]["warm"]["ndcg"]
)

from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(
        encoding="utf-8"
    )
)

for role in lab["scorecards"].values():
    for method, scopes in role.items():
        for scope, s in scopes.items():
            if s["users"]:
                assert s["recall"] <= s["oracle_recall10"] + 1e-12
                assert s["oracle_recall10"] <= s["candidate_recall"] + 1e-12
print(lab["scorecards"]["audit"]["rrf_cf"]["warm"])

from pathlib import Path
import json

lab = json.loads(
    Path("assets/datasets/movielens/recommender_capstone_lab.json").read_text(
        encoding="utf-8"
    )
)

for role, rows in lab["roles"].items():
    cold = [r for r in rows if not r["train_count"] and r["positive"]]
    for row in cold:
        assert all(
            row["sources"][s] == row["sources"]["popularity"]
            for s in ["content", "user_cf"]
        )
    print(role, "cold positives", len(cold))
print("source cases", lab["samples"])

import hashlib
import json

first = {"schema": "বাংলা", "weights": [1, 2]}
second = {"weights": [1, 2], "schema": "বাংলা"}


def canonical(value):
    return (
        json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
        + "\n"
    ).encode("utf-8")


first_bytes, second_bytes = canonical(first), canonical(second)
float_version = {"schema": "বাংলা", "weights": [1.0, 2.0]}
same_hash = (
    hashlib.sha256(first_bytes).digest() == hashlib.sha256(second_bytes).digest()
)
print(
    int(json.dumps(first) != json.dumps(second)),
    int(same_hash),
    int(canonical(float_version) != first_bytes),
    int(first_bytes[:-1] != first_bytes),
)
